<?php
class Reporte_conductor extends CI_Controller{
 private $session_data=array();
 public function __construct(){parent::__construct();if(!$this->session->userdata('logged_in'))redirect('','refresh');$this->session_data=$this->session->userdata('logged_in');$this->load->model('Reporte_conductor_model');$this->load->model('Sistema_model');$this->load->model('Parametro_model');if(!$this->Reporte_conductor_model->usuario_tiene_rol((int)$this->session_data['usuario_id'],220))show_error('No tiene permiso para generar reportes de Transporte.',403,'Acceso denegado');}
 private function filtros(){ $d=trim((string)$this->input->get('desde',true));$h=trim((string)$this->input->get('hasta',true));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$d))$d=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$h))$h=date('Y-m-d');if($d>$h){$x=$d;$d=$h;$h=$x;}return array('desde'=>$d,'hasta'=>$h,'conductor_id'=>(int)$this->input->get('conductor_id',true),'ruta_id'=>(int)$this->input->get('ruta_id',true));}
 public function index(){ $f=$this->filtros();$p=$this->Parametro_model->get_parametros();$data['sistema']=$this->Sistema_model->get_sistema();$data['parametro']=isset($p[0])?$p[0]:$p;$data['filtros']=$f;$data['listas']=$this->Reporte_conductor_model->listas();$data['resumen']=$this->Reporte_conductor_model->resumen($f);$data['detalle']=$this->Reporte_conductor_model->detalle($f);$data['tiene_km']=$this->Reporte_conductor_model->tiene_km();$data['tiene_incidencias']=$this->Reporte_conductor_model->tiene_incidencias();$data['page_title']='Reporte por conductor';$data['_view']='reporte_transporte/conductor';$this->load->view('layouts/main',$data);}
 public function csv(){ $f=$this->filtros();$rs=$this->Reporte_conductor_model->detalle($f);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="reporte_conductores_'.$f['desde'].'_'.$f['hasta'].'.csv"');echo "\xEF\xBB\xBF";$x=fopen('php://output','w');fputcsv($x,array('Fecha','Hora','Conductor','Rol','Ruta','Vehiculo','Pasajeros','Kilometros','Incidencias','Observacion tripulacion'),';');foreach($rs as $r)fputcsv($x,array($r['fecha'],$r['hora'],$r['conductor'],$r['rol'],$r['ruta'],$r['vehiculo'],$r['pasajeros'],$r['kilometros'],$r['incidencias'],$r['observacion']),';');fclose($x);exit;}
}
